import{_ as n,c as a,b as e,o as t}from"./app-DGgJ1dhj.js";const p={};function l(i,s){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="分页导出-excel" tabindex="-1"><a class="header-anchor" href="#分页导出-excel"><span>分页导出 Excel</span></a></h1><h2 id="目录" tabindex="-1"><a class="header-anchor" href="#目录"><span>目录</span></a></h2><ol><li><a href="#%E7%B3%BB%E7%BB%9F%E4%B8%AD%E6%B6%89%E5%8F%8A%E7%9A%84%E4%B8%A4%E7%B1%BB-api">系统中涉及的两类 API</a></li><li><a href="#api-%E4%B8%80%E6%A0%91%E8%8A%82%E7%82%B9%E6%87%92%E5%8A%A0%E8%BD%BD">API 一：树节点懒加载</a></li><li><a href="#api-%E4%BA%8C-%E5%88%86%E9%A1%B5%E5%AF%BC%E5%87%BA">API 二：分页导出</a></li><li><a href="#%E5%AE%8C%E6%95%B4%E7%94%A8%E6%88%B7%E6%93%8D%E4%BD%9C%E6%B5%81%E7%A8%8B">完整用户操作流程</a></li><li><a href="#%E6%9E%B6%E6%9E%84web-worker-%E7%94%9F%E6%88%90-excel">架构：Web Worker 生成 Excel</a></li><li><a href="#%E6%9E%B6%E6%9E%84%E5%8F%97%E6%8E%A7%E5%B9%B6%E8%A1%8C%E8%AF%B7%E6%B1%82">架构：受控并行请求</a></li><li><a href="#%E6%9E%B6%E6%9E%84%E8%BF%9B%E5%BA%A6%E8%8A%82%E6%B5%81">架构：进度节流</a></li><li><a href="#%E6%9E%B6%E6%9E%84%E6%9A%82%E5%81%9C--%E7%BB%A7%E7%BB%AD--%E9%87%8D%E8%AF%95">架构：暂停 / 继续 / 重试</a></li><li><a href="#networkpanel--%E5%AE%9E%E6%97%B6%E6%9F%A5%E7%9C%8B%E6%89%80%E6%9C%89-api-%E8%AF%B7%E6%B1%82">NetworkPanel — 实时查看所有 API 请求</a></li><li><a href="#%E5%88%86%E9%A1%B5%E5%AF%BC%E5%87%BA-vs-%E5%88%86%E7%89%87%E4%B8%8B%E8%BD%BD">分页导出 vs 分片下载</a></li><li><a href="#%E5%9C%A8%E7%9C%9F%E5%AE%9E%E9%A1%B9%E7%9B%AE%E4%B8%AD%E4%BD%BF%E7%94%A8">在真实项目中使用</a></li></ol><hr><h2 id="系统中涉及的两类-api" tabindex="-1"><a class="header-anchor" href="#系统中涉及的两类-api"><span>系统中涉及的两类 API</span></a></h2><p>整个 TreeDemo 中，后端需要提供两类接口：</p><table><thead><tr><th>接口</th><th>用途</th><th>触发时机</th><th>请求频率</th></tr></thead><tbody><tr><td><code>GET /api/tree/children</code></td><td>懒加载子节点</td><td>用户点击展开箭头</td><td>每次展开一个未加载节点</td></tr><tr><td><code>GET /api/tree/export</code></td><td>分页导出数据</td><td>用户点击&quot;开始导出&quot;</td><td>逐页请求，直到全部完成</td></tr></tbody></table><p>两个接口<strong>共享同一个数据库</strong>（demo 中是 <code>nodeMap</code> + <code>flatList</code>），但<strong>查询模式完全不同</strong>：</p><ul><li><code>/api/tree/children</code> — 点查询：<code>WHERE parent_id = ?</code>，返回少量行（3 条）</li><li><code>/api/tree/export</code> — 范围查询：<code>LIMIT 500 OFFSET ?</code>，返回大量行（500 条），用于批量导出![Pasted image 20260611132145](../../../../../_assets/a7721d2-Pasted image 20260611132145.png)</li></ul><hr><h2 id="api-一-树节点懒加载" tabindex="-1"><a class="header-anchor" href="#api-一-树节点懒加载"><span>API 一：树节点懒加载</span></a></h2><h3 id="接口定义" tabindex="-1"><a class="header-anchor" href="#接口定义"><span>接口定义</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">GET /api/tree/children?parentId={nodeId}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="请求示例" tabindex="-1"><a class="header-anchor" href="#请求示例"><span>请求示例</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">GET /api/tree/children?parentId=node_0</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="响应-200-ok" tabindex="-1"><a class="header-anchor" href="#响应-200-ok"><span>响应（200 OK）</span></a></h3><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;code&quot;</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;message&quot;</span><span class="token operator">:</span> <span class="token string">&quot;success&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;data&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;parentId&quot;</span><span class="token operator">:</span> <span class="token string">&quot;node_0&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;children&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">      <span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;node_100&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;parentId&quot;</span><span class="token operator">:</span> <span class="token string">&quot;node_0&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;label&quot;</span><span class="token operator">:</span> <span class="token string">&quot;事业部-0001&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;level&quot;</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;hasChildren&quot;</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;totalChildrenCount&quot;</span><span class="token operator">:</span> <span class="token number">3</span></span>
<span class="line">      <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;node_101&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;parentId&quot;</span><span class="token operator">:</span> <span class="token string">&quot;node_0&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;label&quot;</span><span class="token operator">:</span> <span class="token string">&quot;事业部-0002&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;level&quot;</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;hasChildren&quot;</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;totalChildrenCount&quot;</span><span class="token operator">:</span> <span class="token number">3</span></span>
<span class="line">      <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;node_102&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;parentId&quot;</span><span class="token operator">:</span> <span class="token string">&quot;node_0&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;label&quot;</span><span class="token operator">:</span> <span class="token string">&quot;事业部-0003&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;level&quot;</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;hasChildren&quot;</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;totalChildrenCount&quot;</span><span class="token operator">:</span> <span class="token number">3</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">]</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>![Pasted image 20260611132237](../../../../../_assets/0eba9ca-Pasted image 20260611132237.png)</p><h3 id="响应-204-no-content-—-叶子节点" tabindex="-1"><a class="header-anchor" href="#响应-204-no-content-—-叶子节点"><span>响应（204 No Content — 叶子节点）</span></a></h3><p>当节点已经是叶子节点（没有子节点）时：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">HTTP 204 No Content</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="调用时机" tabindex="-1"><a class="header-anchor" href="#调用时机"><span>调用时机</span></a></h3><p>用户在虚拟滚动列表中点击 <code>▶</code> 箭头展开某个未加载过的节点时触发。前端流程：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">用户点击 ▶ (集团-0001)</span>
<span class="line">  │</span>
<span class="line">  ├─ TreeVirtualList.onToggleExpand(&quot;node_0&quot;)</span>
<span class="line">  ├─ index.tsx: handleToggle(&quot;node_0&quot;)</span>
<span class="line">  │    ├─ 检查 node.childrenLoaded → false</span>
<span class="line">  │    ├─ setLoadingIds → 显示 spinner</span>
<span class="line">  │    ├─ loadChildrenLogged(&quot;node_0&quot;)</span>
<span class="line">  │    │    ├─ 记录 API 日志: GET /api/tree/children?parentId=node_0</span>
<span class="line">  │    │    ├─ 模拟 150-400ms 网络延迟</span>
<span class="line">  │    │    ├─ 生成 3 个子节点 (事业部-0001 ~ 0003)</span>
<span class="line">  │    │    ├─ 写入 nodeMap</span>
<span class="line">  │    │    └─ 记录 API 日志: 200 OK, 215ms</span>
<span class="line">  │    ├─ setDataVersion → 触发 flatList 重算</span>
<span class="line">  │    ├─ setExpandedIds → 展开该节点</span>
<span class="line">  │    └─ setLoadingIds → 移除 spinner</span>
<span class="line">  │</span>
<span class="line">  └─ TreeVirtualList 重渲染 → 显示 3 个子节点（缩进一层）</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="批量加载-展开到第-n-层" tabindex="-1"><a class="header-anchor" href="#批量加载-展开到第-n-层"><span>批量加载（展开到第 N 层）</span></a></h3><p>点击&quot;展开第 2 层&quot;时，系统递归遍历树，对每个未加载节点调用 <code>/api/tree/children</code>，这些请求<strong>并行发出</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">点击&quot;展开第 2 层&quot;</span>
<span class="line">  │</span>
<span class="line">  ├─ 遍历 100 个根节点，发现都没加载过子节点</span>
<span class="line">  ├─ 并行发出 100 个请求:</span>
<span class="line">  │    GET /api/tree/children?parentId=node_0</span>
<span class="line">  │    GET /api/tree/children?parentId=node_1</span>
<span class="line">  │    ...</span>
<span class="line">  │    GET /api/tree/children?parentId=node_99</span>
<span class="line">  │</span>
<span class="line">  ├─ 等待全部完成 → 100 个根节点现在都有 childrenLoaded=true</span>
<span class="line">  ├─ 递归到第 2 层，遍历 300 个子节点</span>
<span class="line">  │    GET /api/tree/children?parentId=node_100</span>
<span class="line">  │    GET /api/tree/children?parentId=node_101</span>
<span class="line">  │    ... (共 300 个请求！)</span>
<span class="line">  │</span>
<span class="line">  └─ setExpandedIds → 展开 400 个节点</span>
<span class="line">     flatList: 100 + 300 + 900 = 1300 行</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>NetworkPanel 中会看到这些请求逐一出现并完成。</p><hr><h2 id="api-二-分页导出-方案-a-前端传展开状态" tabindex="-1"><a class="header-anchor" href="#api-二-分页导出-方案-a-前端传展开状态"><span>API 二：分页导出（方案 A：前端传展开状态）</span></a></h2><h3 id="核心问题" tabindex="-1"><a class="header-anchor" href="#核心问题"><span>核心问题</span></a></h3><p>树数据导出和普通表格导出的关键区别：<strong>导出哪些行取决于当前展开状态</strong>。前端展开了 <code>node_0</code>、<code>node_5</code> 和 <code>node_42</code>，后端必须知道这个信息，否则无法确定递归到哪里停。</p><h3 id="接口定义-1" tabindex="-1"><a class="header-anchor" href="#接口定义-1"><span>接口定义</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">GET /api/tree/export?page={pageIndex}&amp;size={pageSize}&amp;expanded={id1},{id2},{id3},...</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="请求示例-1" tabindex="-1"><a class="header-anchor" href="#请求示例-1"><span>请求示例</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">GET /api/tree/export?page=0&amp;size=100&amp;expanded=node_0,node_1,node_2,...,node_99</span>
<span class="line">GET /api/tree/export?page=1&amp;size=100&amp;expanded=node_0,node_1,node_2,...,node_99</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>每一页请求都携带完整的 <code>expanded</code> 参数——因为后端是无状态的，每次分页请求都需要知道上下文。</p><h3 id="后端-sql-参考实现" tabindex="-1"><a class="header-anchor" href="#后端-sql-参考实现"><span>后端 SQL（参考实现）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="prismjs" data-ext="sql"><pre><code class="language-sql"><span class="line"><span class="token comment">-- 输入: expanded 参数 = &#39;node_0,node_1,...,node_99&#39;</span></span>
<span class="line"><span class="token comment">-- 输出: 深度优先遍历的已展开子树，分页切片</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">WITH</span> RECURSIVE subtree <span class="token keyword">AS</span> <span class="token punctuation">(</span></span>
<span class="line">  <span class="token comment">-- 起点：所有根节点</span></span>
<span class="line">  <span class="token keyword">SELECT</span> id<span class="token punctuation">,</span> label<span class="token punctuation">,</span> <span class="token keyword">level</span><span class="token punctuation">,</span> parent_id<span class="token punctuation">,</span></span>
<span class="line">         total_children_count<span class="token punctuation">,</span> has_children<span class="token punctuation">,</span></span>
<span class="line">         ARRAY<span class="token punctuation">[</span>id<span class="token punctuation">]</span> <span class="token keyword">AS</span> path</span>
<span class="line">  <span class="token keyword">FROM</span> tree_nodes</span>
<span class="line">  <span class="token keyword">WHERE</span> parent_id <span class="token operator">IS</span> <span class="token boolean">NULL</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">UNION</span> <span class="token keyword">ALL</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">-- 递归：只进入 expanded 集合中的节点的子节点</span></span>
<span class="line">  <span class="token keyword">SELECT</span> n<span class="token punctuation">.</span>id<span class="token punctuation">,</span> n<span class="token punctuation">.</span>label<span class="token punctuation">,</span> n<span class="token punctuation">.</span><span class="token keyword">level</span><span class="token punctuation">,</span> n<span class="token punctuation">.</span>parent_id<span class="token punctuation">,</span></span>
<span class="line">         n<span class="token punctuation">.</span>total_children_count<span class="token punctuation">,</span> n<span class="token punctuation">.</span>has_children<span class="token punctuation">,</span></span>
<span class="line">         s<span class="token punctuation">.</span>path <span class="token operator">||</span> n<span class="token punctuation">.</span>id</span>
<span class="line">  <span class="token keyword">FROM</span> tree_nodes n</span>
<span class="line">  <span class="token keyword">JOIN</span> subtree s <span class="token keyword">ON</span> n<span class="token punctuation">.</span>parent_id <span class="token operator">=</span> s<span class="token punctuation">.</span>id</span>
<span class="line">  <span class="token keyword">WHERE</span> s<span class="token punctuation">.</span>id <span class="token operator">=</span> <span class="token keyword">ANY</span><span class="token punctuation">(</span>string_to_array<span class="token punctuation">(</span>:expanded<span class="token punctuation">,</span> <span class="token string">&#39;,&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">SELECT</span> id<span class="token punctuation">,</span> <span class="token keyword">level</span></span>
<span class="line"><span class="token keyword">FROM</span> subtree</span>
<span class="line"><span class="token keyword">ORDER</span> <span class="token keyword">BY</span> path          <span class="token comment">-- 深度优先，与前端 flattenTree 顺序一致</span></span>
<span class="line"><span class="token keyword">LIMIT</span> :size <span class="token keyword">OFFSET</span> :<span class="token keyword">offset</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>关键行是 <code>WHERE s.id = ANY(...)</code> —— 它确保递归只在用户已展开的节点上进行。未展开的节点的子节点<strong>不会</strong>出现在结果中。</p><h3 id="响应-200-ok-1" tabindex="-1"><a class="header-anchor" href="#响应-200-ok-1"><span>响应（200 OK）</span></a></h3><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;code&quot;</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;message&quot;</span><span class="token operator">:</span> <span class="token string">&quot;success&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;data&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;total&quot;</span><span class="token operator">:</span> <span class="token number">400</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;page&quot;</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;size&quot;</span><span class="token operator">:</span> <span class="token number">100</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;totalPages&quot;</span><span class="token operator">:</span> <span class="token number">4</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;rows&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">      <span class="token punctuation">{</span> <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;node_0&quot;</span><span class="token punctuation">,</span>   <span class="token property">&quot;level&quot;</span><span class="token operator">:</span> <span class="token number">0</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token punctuation">{</span> <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;node_100&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;level&quot;</span><span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">      ...</span>
<span class="line">    <span class="token punctuation">]</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="响应-500-internal-server-error-—-模拟故障" tabindex="-1"><a class="header-anchor" href="#响应-500-internal-server-error-—-模拟故障"><span>响应（500 Internal Server Error — 模拟故障）</span></a></h3><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;code&quot;</span><span class="token operator">:</span> <span class="token number">500</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;message&quot;</span><span class="token operator">:</span> <span class="token string">&quot;第 3 页查询失败：数据库连接超时（expanded=node_0,node_1,...）&quot;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="参数说明" tabindex="-1"><a class="header-anchor" href="#参数说明"><span>参数说明</span></a></h3><table><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>page</code></td><td>int</td><td>页码，从 0 开始</td></tr><tr><td><code>size</code></td><td>int</td><td>每页行数，默认 500</td></tr><tr><td><code>expanded</code></td><td>string</td><td>展开的节点 ID，逗号分隔。这些节点及其递归子树会被导出。<strong>未展开的节点的子节点不会出现在结果中</strong></td></tr></tbody></table><h3 id="快照机制" tabindex="-1"><a class="header-anchor" href="#快照机制"><span>快照机制</span></a></h3><p>一个细节：导出开始时，<code>expandedIds</code> 会被<strong>快照</strong>下来（<code>expandedSnapshotRef</code>）。这意味着：</p><ul><li>导出过程中用户继续展开/收起节点 → <strong>不影响正在进行的导出</strong>（后端用的是快照时的 expanded 值）</li><li>暂停后继续 → <strong>使用同一份快照</strong>，保证前后一致性</li><li>如果用户想要导出最新的展开状态 → 需要取消后重新发起导出 | <code>size</code> | int | 每页行数，默认 500 |</li></ul><table><thead><tr><th>响应字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>data.total</code></td><td>int</td><td>总行数（由当前展开状态决定）</td></tr><tr><td><code>data.page</code></td><td>int</td><td>当前页码</td></tr><tr><td><code>data.size</code></td><td>int</td><td>当前页大小（最后一页可能小于 size）</td></tr><tr><td><code>data.totalPages</code></td><td>int</td><td>总页数，前端用于显示进度</td></tr><tr><td><code>data.rows</code></td><td>array</td><td>扁平化的树节点数组，每项含 <code>id</code> 和 <code>level</code></td></tr></tbody></table><h3 id="后端查询逻辑-伪代码" tabindex="-1"><a class="header-anchor" href="#后端查询逻辑-伪代码"><span>后端查询逻辑（伪代码）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="prismjs" data-ext="sql"><pre><code class="language-sql"><span class="line"><span class="token comment">-- 真实后端的等效查询</span></span>
<span class="line"><span class="token keyword">SELECT</span> id<span class="token punctuation">,</span> <span class="token keyword">level</span></span>
<span class="line"><span class="token keyword">FROM</span> tree_nodes</span>
<span class="line"><span class="token keyword">WHERE</span> expanded <span class="token operator">=</span> <span class="token boolean">true</span>          <span class="token comment">-- 只导出已展开节点的子树</span></span>
<span class="line"><span class="token keyword">ORDER</span> <span class="token keyword">BY</span> path                  <span class="token comment">-- 深度优先，保持树的结构顺序</span></span>
<span class="line"><span class="token keyword">LIMIT</span> <span class="token number">500</span> <span class="token keyword">OFFSET</span> <span class="token number">0</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="并行请求策略" tabindex="-1"><a class="header-anchor" href="#并行请求策略"><span>并行请求策略</span></a></h3><p>导出不是逐页串行的，而是受控并行：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">总页数 = 3, concurrency = 3</span>
<span class="line"></span>
<span class="line">  时间 ──────────────────────────────────────────→</span>
<span class="line"></span>
<span class="line">  请求 0:  GET /api/tree/export?page=0&amp;size=500  ──delay──→ 200 OK (96ms)</span>
<span class="line">  请求 1:  GET /api/tree/export?page=1&amp;size=500  ──delay──→ 200 OK (102ms)</span>
<span class="line">  请求 2:  GET /api/tree/export?page=2&amp;size=500  ──delay──→ 200 OK (126ms)</span>
<span class="line"></span>
<span class="line">  三路并发，总耗时 ≈ max(96, 102, 126) ≈ 126ms</span>
<span class="line">  串行的话总耗时 = 96 + 102 + 126 = 324ms</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果总页数超过 concurrency（如 10 页，concurrency=3），则分 4 批：</p><ul><li>第 1 批：页 0, 1, 2（并行）</li><li>第 2 批：页 3, 4, 5（并行）</li><li>第 3 批：页 6, 7, 8（并行）</li><li>第 4 批：页 9（单独）</li></ul><hr><h2 id="完整用户操作流程" tabindex="-1"><a class="header-anchor" href="#完整用户操作流程"><span>完整用户操作流程</span></a></h2><p>以下是从打开页面到导出的完整操作序列，以及每一步触发的 API 调用。</p><h3 id="第一步-打开页面" tabindex="-1"><a class="header-anchor" href="#第一步-打开页面"><span>第一步：打开页面</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">浏览器: GET http://localhost:5177/yike/src-react/#/tree-demo</span>
<span class="line">  → 加载 React SPA</span>
<span class="line">  → 初始化树数据: createLazyTreeData()</span>
<span class="line">  → 初始状态: 100 个根节点可见（未展开）</span>
<span class="line">  → flatList: 100 行</span>
<span class="line">  → NetworkPanel: 空（还没有 API 调用）</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="第二步-展开单个节点" tabindex="-1"><a class="header-anchor" href="#第二步-展开单个节点"><span>第二步：展开单个节点</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">用户: 点击 集团-0001 的 ▶ 箭头</span>
<span class="line"></span>
<span class="line">NetworkPanel 显示:</span>
<span class="line">  ┌────────────────────────────────────────────────────┐</span>
<span class="line">  │ TREE │ 200 │ GET │ /api/tree/children?parentId=   │</span>
<span class="line">  │      │     │     │ node_0 │ 215ms │ 1.2KB         │</span>
<span class="line">  └────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">前端变化:</span>
<span class="line">  - 集团-0001 展开，显示 3 个子节点</span>
<span class="line">  - flatList: 103 行</span>
<span class="line">  - &quot;已加载&quot; 统计: 0 → 1</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="第三步-批量展开" tabindex="-1"><a class="header-anchor" href="#第三步-批量展开"><span>第三步：批量展开</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">用户: 点击&quot;展开第 1 层&quot;</span>
<span class="line"></span>
<span class="line">NetworkPanel 显示:</span>
<span class="line">  ┌────────────────────────────────────────────────────┐</span>
<span class="line">  │ TREE │ 200 │ GET │ ...?parentId=node_1  │ 189ms   │</span>
<span class="line">  │ TREE │ 200 │ GET │ ...?parentId=node_2  │ 201ms   │</span>
<span class="line">  │ ...  │     │     │ (100 条请求)         │         │</span>
<span class="line">  └────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">前端变化:</span>
<span class="line">  - 所有 100 个根节点展开</span>
<span class="line">  - flatList: 400 行</span>
<span class="line">  - &quot;可见&quot;: 400 行, &quot;展开&quot;: 100 个</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="第四步-发起导出-携带-expanded-参数" tabindex="-1"><a class="header-anchor" href="#第四步-发起导出-携带-expanded-参数"><span>第四步：发起导出（携带 expanded 参数）</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">用户: 点击&quot;开始导出&quot;</span>
<span class="line"></span>
<span class="line">ExportPanel 状态: 导出中…（3 个并行请求）</span>
<span class="line"></span>
<span class="line">NetworkPanel 显示:</span>
<span class="line">  ┌────────────────────────────────────────────────────┐</span>
<span class="line">  │ TREE    │ 200 │ ... (之前的树节点请求)              │</span>
<span class="line">  │ EXPORT  │ 200 │ GET │ /api/tree/export?page=0      │</span>
<span class="line">  │         │     │     │ &amp;size=100&amp;expanded=node_0,    │</span>
<span class="line">  │         │     │     │ node_1,node_2...（共 100 个） │</span>
<span class="line">  │         │     │     │               96ms │ 11.4KB   │</span>
<span class="line">  └────────────────────────────────────────────────────┘</span>
<span class="line"></span>
<span class="line">内部流程:</span>
<span class="line">  1. 快照 expandedIds → expandedSnapshotRef</span>
<span class="line">  2. 构造 URL: /api/tree/export?page=0&amp;size=100&amp;expanded=node_0,node_1,...</span>
<span class="line"></span>
<span class="line">  主线程                            Worker 线程</span>
<span class="line">    ├─ apiClient.fetchPage(0)        │</span>
<span class="line">    │    ├─ 根据 expandedIds 运行     │</span>
<span class="line">    │    │   flattenTree → flatList  │</span>
<span class="line">    │    ├─ slice(0, 100) → rows    │</span>
<span class="line">    │    └─ postMessage({ rows }) ──→├─ sheet_add_json</span>
<span class="line">    │                                │</span>
<span class="line">    ├─ 全部页完成                     │</span>
<span class="line">    ├─ postMessage({ finish }) ─────→├─ XLSX.write() → Blob</span>
<span class="line">    │                                │</span>
<span class="line">    │←── postMessage({ blob }) ──────┤</span>
<span class="line">    │                                │</span>
<span class="line">    └─ 导出完成                       │</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意：导出过程中如果用户继续展开/收起节点，<strong>不影响正在进行的导出</strong>——因为 <code>expandedSnapshotRef</code> 已经快照下来了。</p><h3 id="第五步-下载" tabindex="-1"><a class="header-anchor" href="#第五步-下载"><span>第五步：下载</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">用户: 点击&quot;下载 Excel (400 行)&quot;</span>
<span class="line"></span>
<span class="line">浏览器: 触发下载 tree-export-{timestamp}.xlsx</span>
<span class="line"></span>
<span class="line">文件内容:</span>
<span class="line">  ┌──────┬──────────┬────────────┬──────┬──────────┬─────────┬─────────┐</span>
<span class="line">  │ 序号 │ 节点ID   │ 标签       │ 层级 │ 父节点ID │ 子节点数│ 是否叶子│</span>
<span class="line">  ├──────┼──────────┼────────────┼──────┼──────────┼─────────┼─────────┤</span>
<span class="line">  │ 1    │ node_0   │ 集团-0001  │ 0    │          │ 3       │ 否      │</span>
<span class="line">  │ 2    │ node_100 │ 事业部-0001│ 1    │ node_0   │ 3       │ 否      │</span>
<span class="line">  │ 3    │ node_101 │ 事业部-0002│ 1    │ node_0   │ 3       │ 否      │</span>
<span class="line">  │ 4    │ node_102 │ 事业部-0003│ 1    │ node_0   │ 3       │ 否      │</span>
<span class="line">  │ 5    │ node_1   │ 集团-0002  │ 0    │          │ 3       │ 否      │</span>
<span class="line">  │ ...  │ ...      │ ...        │ ...  │ ...      │ ...     │ ...     │</span>
<span class="line">  └──────┴──────────┴────────────┴──────┴──────────┴─────────┴─────────┘</span>
<span class="line"></span>
<span class="line">  树结构通过&quot;层级&quot;列和&quot;父节点ID&quot;列体现，可在 Excel 中筛选/排序/重建树关系。</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="架构-web-worker-生成-excel" tabindex="-1"><a class="header-anchor" href="#架构-web-worker-生成-excel"><span>架构：Web Worker 生成 Excel</span></a></h2><p>SheetJS 的 <code>XLSX.write()</code> 是同步 CPU 密集操作。在 UI 线程上生成 10 万行的 Excel 会导致页面冻结 1-3 秒。</p><p><strong>解决方案</strong>：将 Excel 生成移到 Web Worker。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">主线程 (协调)                    Worker 线程 (CPU 密集)</span>
<span class="line">  │                                    │</span>
<span class="line">  ├─ fetch page 0 → rows               │</span>
<span class="line">  ├─ postMessage({ addRows }) ────────→├─ XLSX.utils.sheet_add_json()</span>
<span class="line">  ├─ fetch page 1 → rows               │   (增量追加，不重建 sheet)</span>
<span class="line">  ├─ postMessage({ addRows }) ────────→│</span>
<span class="line">  ├─ ...                               │</span>
<span class="line">  ├─ postMessage({ finish }) ─────────→├─ XLSX.write() → Blob</span>
<span class="line">  │                                    │   ← 这是唯一的 CPU 密集操作</span>
<span class="line">  │←── postMessage({ complete, blob })─┤</span>
<span class="line">  └─ 创建下载链接                       │</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Worker 代码在 <code>export.worker.ts</code>。关键 API：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// 第一批：创建 sheet + 表头</span></span>
<span class="line">worksheet <span class="token operator">=</span> <span class="token constant">XLSX</span><span class="token punctuation">.</span>utils<span class="token punctuation">.</span><span class="token function">json_to_sheet</span><span class="token punctuation">(</span>firstBatchRows<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 后续批次：追加到最后一行</span></span>
<span class="line"><span class="token constant">XLSX</span><span class="token punctuation">.</span>utils<span class="token punctuation">.</span><span class="token function">sheet_add_json</span><span class="token punctuation">(</span>worksheet<span class="token punctuation">,</span> nextBatchRows<span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">  origin<span class="token operator">:</span> <span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">,</span>        <span class="token comment">// 追加模式</span></span>
<span class="line">  skipHeader<span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span>  <span class="token comment">// 不重复表头</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 最终：写入 xlsx（CPU 密集，但发生在 Worker 线程）</span></span>
<span class="line"><span class="token keyword">const</span> buf <span class="token operator">=</span> <span class="token constant">XLSX</span><span class="token punctuation">.</span><span class="token function">write</span><span class="token punctuation">(</span>wb<span class="token punctuation">,</span> <span class="token punctuation">{</span> bookType<span class="token operator">:</span> <span class="token string">&#39;xlsx&#39;</span><span class="token punctuation">,</span> type<span class="token operator">:</span> <span class="token string">&#39;array&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="worker-消息协议" tabindex="-1"><a class="header-anchor" href="#worker-消息协议"><span>Worker 消息协议</span></a></h3><table><thead><tr><th>消息</th><th>方向</th><th>作用</th></tr></thead><tbody><tr><td><code>{ type:&#39;addRows&#39;, rows }</code></td><td>主→Worker</td><td>追加一批行</td></tr><tr><td><code>{ type:&#39;finish&#39; }</code></td><td>主→Worker</td><td>完成，写入 xlsx 返回 Blob</td></tr><tr><td><code>{ type:&#39;ready&#39; }</code></td><td>Worker→主</td><td>Worker 就绪</td></tr><tr><td><code>{ type:&#39;rowsAdded&#39;, count, total }</code></td><td>Worker→主</td><td>行数更新</td></tr><tr><td><code>{ type:&#39;complete&#39;, blob }</code></td><td>Worker→主</td><td>最终 Excel Blob</td></tr></tbody></table><hr><h2 id="架构-受控并行请求" tabindex="-1"><a class="header-anchor" href="#架构-受控并行请求"><span>架构：受控并行请求</span></a></h2><p>串行请求的问题：100 页 × 每页 200ms = 20 秒总耗时。</p><p>解决方案：批量并行，每批 concurrency=3 个请求同时发出。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">while</span> <span class="token punctuation">(</span>cursor <span class="token operator">&lt;</span> pendingPages<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> batch <span class="token operator">=</span> pendingPages<span class="token punctuation">.</span><span class="token function">slice</span><span class="token punctuation">(</span>cursor<span class="token punctuation">,</span> cursor <span class="token operator">+</span> concurrency<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">const</span> promises <span class="token operator">=</span> batch<span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token punctuation">(</span>pageIndex<span class="token punctuation">)</span> <span class="token operator">=&gt;</span></span>
<span class="line">    apiClient<span class="token punctuation">.</span><span class="token function">fetchPage</span><span class="token punctuation">(</span>pageIndex<span class="token punctuation">,</span> signal<span class="token punctuation">)</span></span>
<span class="line">      <span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span>response <span class="token operator">=&gt;</span> <span class="token punctuation">(</span><span class="token punctuation">{</span> success<span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span> pageIndex<span class="token punctuation">,</span> response <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">      <span class="token punctuation">.</span><span class="token function">catch</span><span class="token punctuation">(</span>err    <span class="token operator">=&gt;</span> <span class="token punctuation">(</span><span class="token punctuation">{</span> success<span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span> pageIndex<span class="token punctuation">,</span> error<span class="token operator">:</span> err <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">const</span> results <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token builtin">Promise</span><span class="token punctuation">.</span><span class="token function">allSettled</span><span class="token punctuation">(</span>promises<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> settled <span class="token keyword">of</span> results<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 分别处理成功/失败</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  cursor <span class="token operator">+=</span> concurrency</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="promise-allsettled-vs-promise-all" tabindex="-1"><a class="header-anchor" href="#promise-allsettled-vs-promise-all"><span>Promise.allSettled vs Promise.all</span></a></h3><table><thead><tr><th></th><th>Promise.all</th><th>Promise.allSettled</th></tr></thead><tbody><tr><td>一个失败后</td><td>立即 reject，其余请求被丢弃</td><td>继续等待其他请求完成</td></tr><tr><td>返回值</td><td>只返回成功的值</td><td>每个结果带 <code>status: &#39;fulfilled&#39; / &#39;rejected&#39;</code></td></tr><tr><td>导出适用性</td><td>不适用 — 一页失败不应导致整批作废</td><td>正确选择 — 分别处理每页</td></tr></tbody></table><hr><h2 id="架构-进度节流" tabindex="-1"><a class="header-anchor" href="#架构-进度节流"><span>架构：进度节流</span></a></h2><p>导出过程中每页完成都会触发进度更新。不加控制的话，200 页就是 200 次 React 重渲染。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">let</span> lastEmit <span class="token operator">=</span> <span class="token number">0</span></span>
<span class="line"><span class="token keyword">const</span> <span class="token function-variable function">emitProgress</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>Date<span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-</span> lastEmit <span class="token operator">&lt;</span> <span class="token number">100</span><span class="token punctuation">)</span> <span class="token keyword">return</span>  <span class="token comment">// 最多 10fps</span></span>
<span class="line">  lastEmit <span class="token operator">=</span> Date<span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token function">onProgress</span><span class="token punctuation">(</span><span class="token punctuation">{</span> totalPages<span class="token punctuation">,</span> completedPages<span class="token punctuation">,</span> <span class="token operator">...</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="架构-暂停-继续-重试" tabindex="-1"><a class="header-anchor" href="#架构-暂停-继续-重试"><span>架构：暂停 / 继续 / 重试</span></a></h2><p>暂停时需要同时中止两件事：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> <span class="token function-variable function">pauseExport</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  abortRef<span class="token punctuation">.</span>current<span class="token operator">?.</span><span class="token function">abort</span><span class="token punctuation">(</span><span class="token punctuation">)</span>      <span class="token comment">// ① 中止进行中的 fetch (via signal)</span></span>
<span class="line">  apiClientRef<span class="token punctuation">.</span>current<span class="token operator">?.</span><span class="token function">cancel</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token comment">// ② 标记 API client 为已取消 (阻止延迟中的请求)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>继续时重建 AbortController 和 API Client，通过 <code>skipPages</code> 跳过已处理页。详见 <code>exportService.ts</code> 的 <code>ExportOptions</code>。</p><hr><h2 id="networkpanel-—-实时查看所有-api-请求" tabindex="-1"><a class="header-anchor" href="#networkpanel-—-实时查看所有-api-请求"><span>NetworkPanel — 实时查看所有 API 请求</span></a></h2><p>页面顶部（控制栏下方）有一个统一的 Network 面板，模拟 Chrome DevTools 风格：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌──────────────────────────────────────────────────────────┐</span>
<span class="line">│ Network — API 请求日志  TREE 1  EXPORT 3         4 条    │</span>
<span class="line">├──────────────────────────────────────────────────────────┤</span>
<span class="line">│ 12:50:52  TREE   200  GET  /api/tree/children?parentId= │</span>
<span class="line">│              node_0                       215ms  1.2KB   │</span>
<span class="line">│ 12:51:15  EXPORT 200  GET  /api/tree/export?page=0&amp;size │</span>
<span class="line">│              =500                          96ms 11.4KB   │</span>
<span class="line">│ 12:51:15  EXPORT 200  GET  /api/tree/export?page=1&amp;size │</span>
<span class="line">│              =500                         102ms 13.8KB   │</span>
<span class="line">│ 12:51:15  EXPORT 200  GET  /api/tree/export?page=2&amp;size │</span>
<span class="line">│              =500                         126ms 11.4KB   │</span>
<span class="line">└──────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>颜色编码：</p><table><thead><tr><th>标签</th><th>颜色</th><th>含义</th></tr></thead><tbody><tr><td>TREE</td><td>蓝</td><td>树节点懒加载请求</td></tr><tr><td>EXPORT</td><td>橙</td><td>分页导出请求</td></tr><tr><td>200</td><td>绿</td><td>请求成功</td></tr><tr><td>500</td><td>红</td><td>请求失败</td></tr></tbody></table><p>每条日志包含：时间戳、类型标签、HTTP 状态码、方法、URL、耗时、响应体大小。</p><p>ExportPanel 内部也有一个独立的导出 Network 面板，hover 条目可 preview 完整响应体。</p><hr><h2 id="分页导出-vs-分片下载" tabindex="-1"><a class="header-anchor" href="#分页导出-vs-分片下载"><span>分页导出 vs 分片下载</span></a></h2><table><thead><tr><th>维度</th><th>分页导出</th><th>分片下载</th></tr></thead><tbody><tr><td><strong>操作对象</strong></td><td>结构化数据集合（数据库行）</td><td>单个大文件</td></tr><tr><td><strong>请求 URL</strong></td><td><code>GET /api/export?page=0&amp;size=500</code></td><td><code>GET /file.mp4</code> + <code>Range: bytes=0-1048575</code></td></tr><tr><td><strong>组装位置</strong></td><td>应用层（Worker 中逐批写入 xlsx）</td><td>系统层（按字节偏移拼接）</td></tr><tr><td><strong>协议</strong></td><td>REST 分页参数</td><td>HTTP Range 头</td></tr><tr><td><strong>暂停粒度</strong></td><td>以&quot;页&quot;为单位</td><td>以&quot;字节段&quot;为单位</td></tr><tr><td><strong>失败恢复</strong></td><td>标记某页失败，其余继续</td><td>重试失败字节段</td></tr></tbody></table><hr><h2 id="在真实项目中使用" tabindex="-1"><a class="header-anchor" href="#在真实项目中使用"><span>在真实项目中使用</span></a></h2><h3 id="需要替换的部分" tabindex="-1"><a class="header-anchor" href="#需要替换的部分"><span>需要替换的部分</span></a></h3><p><strong>1. 后端 API 实现</strong></p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// 替换 apiSimulator.ts → 真实后端接口</span></span>
<span class="line"><span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">fetchPage</span><span class="token punctuation">(</span>pageIndex<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">,</span> signal<span class="token operator">:</span> AbortSignal<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> res <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">fetch</span><span class="token punctuation">(</span></span>
<span class="line">    <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">/api/tree/export?page=</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>pageIndex<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">&amp;size=500</span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">{</span> signal <span class="token punctuation">}</span>  <span class="token comment">// ← AbortController 直接传给 fetch</span></span>
<span class="line">  <span class="token punctuation">)</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>res<span class="token punctuation">.</span>ok<span class="token punctuation">)</span> <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">Error</span><span class="token punctuation">(</span><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">HTTP </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>res<span class="token punctuation">.</span>status<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token keyword">return</span> res<span class="token punctuation">.</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>2. 后端导出接口的实现要点</strong></p><div class="language-sql line-numbers-mode" data-highlighter="prismjs" data-ext="sql"><pre><code class="language-sql"><span class="line"><span class="token comment">-- expanded 参数示例: &quot;node_0,node_1,node_2,...,node_99&quot;</span></span>
<span class="line"><span class="token comment">-- 接口: GET /api/tree/export?page=0&amp;size=100&amp;expanded=node_0,node_1,...</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">WITH</span> RECURSIVE subtree <span class="token keyword">AS</span> <span class="token punctuation">(</span></span>
<span class="line">  <span class="token keyword">SELECT</span> id<span class="token punctuation">,</span> label<span class="token punctuation">,</span> <span class="token keyword">level</span><span class="token punctuation">,</span> parent_id<span class="token punctuation">,</span></span>
<span class="line">         total_children_count<span class="token punctuation">,</span> has_children<span class="token punctuation">,</span></span>
<span class="line">         ARRAY<span class="token punctuation">[</span>id<span class="token punctuation">]</span> <span class="token keyword">AS</span> path</span>
<span class="line">  <span class="token keyword">FROM</span> tree_nodes <span class="token keyword">WHERE</span> parent_id <span class="token operator">IS</span> <span class="token boolean">NULL</span></span>
<span class="line">  <span class="token keyword">UNION</span> <span class="token keyword">ALL</span></span>
<span class="line">  <span class="token keyword">SELECT</span> n<span class="token punctuation">.</span>id<span class="token punctuation">,</span> n<span class="token punctuation">.</span>label<span class="token punctuation">,</span> n<span class="token punctuation">.</span><span class="token keyword">level</span><span class="token punctuation">,</span> n<span class="token punctuation">.</span>parent_id<span class="token punctuation">,</span></span>
<span class="line">         n<span class="token punctuation">.</span>total_children_count<span class="token punctuation">,</span> n<span class="token punctuation">.</span>has_children<span class="token punctuation">,</span></span>
<span class="line">         s<span class="token punctuation">.</span>path <span class="token operator">||</span> n<span class="token punctuation">.</span>id</span>
<span class="line">  <span class="token keyword">FROM</span> tree_nodes n</span>
<span class="line">  <span class="token keyword">JOIN</span> subtree s <span class="token keyword">ON</span> n<span class="token punctuation">.</span>parent_id <span class="token operator">=</span> s<span class="token punctuation">.</span>id</span>
<span class="line">  <span class="token keyword">WHERE</span> s<span class="token punctuation">.</span>id <span class="token operator">=</span> <span class="token keyword">ANY</span><span class="token punctuation">(</span>string_to_array<span class="token punctuation">(</span>:expanded<span class="token punctuation">,</span> <span class="token string">&#39;,&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">     <span class="token comment">-- ↑ 关键：只在展开的节点上递归</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">SELECT</span> id<span class="token punctuation">,</span> <span class="token keyword">level</span></span>
<span class="line"><span class="token keyword">FROM</span> subtree</span>
<span class="line"><span class="token keyword">ORDER</span> <span class="token keyword">BY</span> path        <span class="token comment">-- 深度优先，与 flattenTree 一致</span></span>
<span class="line"><span class="token keyword">LIMIT</span> :size <span class="token keyword">OFFSET</span> :<span class="token keyword">offset</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>3. 前端调用示例</strong></p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> expandedIds <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string">&#39;node_0&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;node_1&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;node_2&#39;</span><span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">]</span> <span class="token comment">// 100 个展开的节点 ID</span></span>
<span class="line"><span class="token keyword">const</span> url <span class="token operator">=</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">/api/tree/export?page=0&amp;size=100&amp;expanded=</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>expandedIds<span class="token punctuation">.</span><span class="token function">join</span><span class="token punctuation">(</span><span class="token string">&#39;,&#39;</span><span class="token punctuation">)</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span></span>
<span class="line"><span class="token keyword">const</span> response <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">fetch</span><span class="token punctuation">(</span>url<span class="token punctuation">,</span> <span class="token punctuation">{</span> signal<span class="token operator">:</span> abortController<span class="token punctuation">.</span>signal <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="不需要改的部分" tabindex="-1"><a class="header-anchor" href="#不需要改的部分"><span>不需要改的部分</span></a></h3><p>以下代码在对接真实后端后<strong>完全不变</strong>：</p><ul><li><code>export.worker.ts</code> — Worker 只接收行数据、生成 Excel，不关心数据来源</li><li><code>PaginatedExporter.startExport()</code> — 并行控制、<code>Promise.allSettled</code>、节流逻辑</li><li><code>ExportPanel</code> 的暂停/继续/重试状态机</li><li><code>NetworkPanel</code> — 真实后端用 DevTools Network 面板即可</li></ul><hr><h2 id="文件清单" tabindex="-1"><a class="header-anchor" href="#文件清单"><span>文件清单</span></a></h2><table><thead><tr><th>文件</th><th>作用</th></tr></thead><tbody><tr><td><code>mockData.ts</code></td><td>树数据生成（100k 节点，7 层），懒加载模拟</td></tr><tr><td><code>apiSimulator.ts</code></td><td>模拟分页导出 API + 请求/响应日志</td></tr><tr><td><code>exportService.ts</code></td><td>导出引擎：并行控制、节流、Worker 协调</td></tr><tr><td><code>export.worker.ts</code></td><td>Web Worker，增量生成 Excel，脱离主线程</td></tr><tr><td><code>ExportPanel.tsx</code></td><td>导出配置面板 + 进度 + 内部 Network 面板</td></tr><tr><td><code>NetworkPanel.tsx</code></td><td>统一 Network 面板（树 API + 导出 API）</td></tr><tr><td><code>TreeVirtualList.tsx</code></td><td>虚拟滚动展示模式</td></tr><tr><td><code>TreePaginatedList.tsx</code></td><td>分页展示模式（扁平表格）</td></tr><tr><td><code>index.tsx</code></td><td>页面入口，模式切换，统一 API 日志管理</td></tr></tbody></table><hr><h2 id="实测性能数据" tabindex="-1"><a class="header-anchor" href="#实测性能数据"><span>实测性能数据</span></a></h2><p>测试环境：Windows 11, Chrome, Vite dev server, 1,300 行树数据（100 根节点 + 300 一层子节点 + 900 二层子节点）。</p><h3 id="内存占用" tabindex="-1"><a class="header-anchor" href="#内存占用"><span>内存占用</span></a></h3><table><thead><tr><th>阶段</th><th>已用 JS 堆</th><th>增量</th><th>说明</th></tr></thead><tbody><tr><td>页面初始 (100 行可见)</td><td>50.0 MB</td><td>—</td><td>基础开销：React + Arco + 树组件 + 100 个 TreeNode</td></tr><tr><td>展开到第 2 层 (1,300 行)</td><td>55.9 MB</td><td>+5.9 MB</td><td>新增 300 个 TreeNode，flatList 从 100→1,300 条</td></tr><tr><td>Worker 导出中（峰值）</td><td>55.9 MB</td><td>+0</td><td>每页数据通过 postMessage 发 Worker，主线程不囤积</td></tr><tr><td>导出完成后</td><td>54.1 MB</td><td>-1.8 MB</td><td>GC 回收临时数据</td></tr></tbody></table><p><strong>结论</strong>：<code>flatList</code> 的 <code>{id, level}</code> 对象非常轻量（~4 KB/千条），主要内存增长来自 <code>nodeMap</code> 中新增的 <code>TreeNode</code>。导出过程内存稳定，无泄漏。</p><h3 id="worker-vs-主线程-excel-生成" tabindex="-1"><a class="header-anchor" href="#worker-vs-主线程-excel-生成"><span>Worker vs 主线程 Excel 生成</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">测试方法：对 N 行数据依次执行 XLSX.utils.json_to_sheet + XLSX.write</span>
<span class="line">Worker 组：在 export.worker.ts 中执行，主线程无感知</span>
<span class="line">主线程组：直接在页面主线程执行，测量冻结时长</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>数据量</th><th>主线程同步耗时</th><th>Worker 方案</th><th>主线程冻结</th></tr></thead><tbody><tr><td>1,300 行</td><td>111 ms</td><td>0 ms</td><td>短促卡顿</td></tr><tr><td>10,000 行</td><td>627 ms</td><td>0 ms</td><td>0.6 秒明显冻结</td></tr><tr><td>50,000 行</td><td>3,625 ms</td><td>0 ms</td><td><strong>3.6 秒完全无响应</strong></td></tr></tbody></table><p>随着行数增长，<code>XLSX.write()</code> 的耗时近似线性增长（~7ms / 千行）。Worker 将这 111ms~3.6s 的同步阻塞完全移出主线程。</p><h3 id="受控并行-vs-串行网络请求" tabindex="-1"><a class="header-anchor" href="#受控并行-vs-串行网络请求"><span>受控并行 vs 串行网络请求</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">测试方法：3 页数据，每页模拟 80-250ms 网络延迟</span>
<span class="line">串行组：concurrency=1，逐页请求</span>
<span class="line">并行组：concurrency=3，三路并发</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>策略</th><th>总网络等待时间</th><th>加速比</th></tr></thead><tbody><tr><td>串行</td><td>~360ms (120×3)</td><td>1×</td></tr><tr><td>并行 (concurrency=3)</td><td>~120ms (最慢者)</td><td><strong>3×</strong></td></tr></tbody></table><p>&gt; 注意：真实项目的网络延迟通常在 50-500ms 之间，串行 200 页需要 10-100 秒。concurrency=3 的并行可将总时间缩短到 1/3。</p><h3 id="进度节流效果" tabindex="-1"><a class="header-anchor" href="#进度节流效果"><span>进度节流效果</span></a></h3><table><thead><tr><th>节流策略</th><th>200 页导出期间 React 重渲染次数</th></tr></thead><tbody><tr><td>无节流</td><td>200 次（每页触发一次 setState）</td></tr><tr><td>100ms 节流</td><td>~8 次（每秒最多 10 帧）</td></tr></tbody></table><p>节省了 <strong>96% 的不必要重渲染</strong>。</p><h3 id="策略有效性总览" tabindex="-1"><a class="header-anchor" href="#策略有效性总览"><span>策略有效性总览</span></a></h3><table><thead><tr><th>策略</th><th>实测效果</th><th>关键指标</th></tr></thead><tbody><tr><td>Web Worker 生成 Excel</td><td>将 111ms~3.6s 主线程阻塞降为 0</td><td>导出时页面可继续滚动、切换模式</td></tr><tr><td>受控并行 (concurrency=3)</td><td>网络等待时间 ÷ 3</td><td>3 页从 360ms → 120ms</td></tr><tr><td>进度节流 (100ms)</td><td>重渲染次数减少 96%</td><td>200 次 → ~8 次</td></tr><tr><td>增量 Worker 写入</td><td>内存不随总行数增长</td><td>1,300 行和 50,000 行内存占用相同</td></tr><tr><td>expanded 快照</td><td>导出中展开/收起不影响当前导出</td><td>数据一致性保证</td></tr></tbody></table>`,141)])])}const o=n(p,[["render",l]]),d=JSON.parse('{"path":"/notes/obsidian/%E5%89%8D%E7%AB%AF/%E9%9D%A2%E8%AF%95/%E9%A1%B9%E7%9B%AE/Quota_%E7%81%AB%E5%B1%B1BABI/%E6%97%A7%E7%AE%80%E5%8E%86%E5%AE%9E%E4%B9%A0/%E5%88%86%E9%A1%B5%E5%AF%BC%E5%87%BA%20Excel%20%E2%8C%9A%EF%B8%8F%F0%9F%8C%9F.html","title":"分页导出 Excel","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"notes/obsidian/前端/面试/项目/Quota&火山BABI/旧简历实习/分页导出 Excel ⌚️🌟.md"}');export{o as comp,d as data};
